#!/usr/bin/env python3
"""Run the real sample generator and capture/compare every generated byte.

Use the same --work-dir for baseline and candidate runs: UE import settings
contain absolute filenames. No output fields, whitespace or ordering are ignored.
Only the runtime log and unchanged input descriptors are excluded.
"""

import argparse
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def run(args):
    repository = Path(__file__).resolve().parent.parent
    jar = args.jar.resolve(strict=True)
    work = args.work_dir.resolve()
    snapshot = args.snapshot.resolve()
    sample = work / "sample"
    # This tool owns only this explicitly marked fixture, never the real sample.
    marker = work / ".xresloader-sample-regression"
    if work == repository or repository.is_relative_to(work) or work.is_relative_to(repository / "sample"):
        raise ValueError("--work-dir must not contain the repository or be inside sample")
    if jar.is_relative_to(sample) or snapshot.is_relative_to(sample):
        raise ValueError("The JAR and snapshot must be outside the disposable sample fixture")
    if args.capture and snapshot.exists():
        raise FileExistsError(f"Baseline already exists: {snapshot}")
    work.mkdir(parents=True, exist_ok=True)
    if sample.exists():
        if not marker.is_file():
            raise ValueError(f"Refusing to replace an unmarked fixture: {sample}")
        shutil.rmtree(sample)
    marker.touch()
    sample.mkdir()
    for source in (repository / "sample").iterdir():
        if source.is_file() and (source.suffix in (".xlsx", ".xls", ".ini", ".json", ".js", ".yaml", ".txt")
                                 or source.name in ("gen_sample_output.ps1", "gen_sample_output.sh")):
            shutil.copy2(source, sample / source.name)
    for protocol in ("proto_v2", "proto_v3"):
        destination = sample / protocol
        destination.mkdir()
        for source in (repository / "sample" / protocol).iterdir():
            if source.suffix in (".proto", ".pb"):
                shutil.copy2(source, destination / source.name)
    inputs = {p.relative_to(sample).as_posix(): digest(p) for p in sample.rglob("*") if p.is_file()}
    if os.name == "nt":
        shell = shutil.which("pwsh") or shutil.which("powershell")
        if not shell:
            raise RuntimeError("PowerShell is required to execute the Windows sample script")
        command = [shell, "-NoProfile", "-ExecutionPolicy", "Bypass", "-File",
                   str(sample / "gen_sample_output.ps1"), "-XresloaderJar", str(jar)]
    else:
        command = ["bash", str(sample / "gen_sample_output.sh")]
    environment = dict(os.environ, XRESLOADER=str(jar))
    log = work / "generator.log"
    with log.open("wb") as output:
        subprocess.run(command, cwd=sample, env=environment, stdout=output,
                       stderr=subprocess.STDOUT, check=True, timeout=300)
    outputs = {p.relative_to(sample).as_posix(): digest(p) for p in sample.rglob("*")
               if p.is_file() and p.suffix != ".log" and p.relative_to(sample).as_posix() not in inputs}
    for name, expected in inputs.items():
        if digest(sample / name) != expected:
            raise AssertionError(f"Sample generator changed input: {name}")
    # Ensure the stdin batch actually ran; a successful JVM exit alone is insufficient.
    for protocol in ("proto_v2", "proto_v3"):
        for filename in ("role_cfg.bin", "role_cfg.json", "role_cfg.msgpack.bin", "role_cfg.xml",
                         "role_cfg.js", "role_cfg.lua", "process_by_script.bin", "process_by_script.json",
                         "field_alias.bin", "global_settings.lua", "enum_and_in_table.lua",
                         "json/ArrInArrCfg.json", "csv/ArrInArrCfgRec.csv"):
            if f"{protocol}/{filename}" not in outputs:
                raise AssertionError(f"Missing sample output: {protocol}/{filename}; see {log}")
    manifest = {"format": 1, "platform": os.name, "fixture": str(sample),
                "jarSha256": digest(jar), "inputs": inputs, "outputs": outputs}
    if args.capture:
        snapshot.parent.mkdir(parents=True, exist_ok=True)
        snapshot.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        print(f"Captured {len(outputs)} sample outputs: {snapshot}")
    else:
        baseline = json.loads(snapshot.read_text(encoding="utf-8"))
        for key in ("format", "platform", "fixture", "inputs"):
            if baseline[key] != manifest[key]:
                raise AssertionError(f"Baseline {key} differs; use identical fixtures, platform and work directory")
        before = baseline["outputs"]
        added = sorted(outputs.keys() - before.keys())
        removed = sorted(before.keys() - outputs.keys())
        changed = sorted(name for name in before.keys() & outputs.keys() if before[name] != outputs[name])
        report = {"baselineJarSha256": baseline["jarSha256"], "candidateJarSha256": manifest["jarSha256"],
                  "compared": len(outputs), "added": added, "removed": removed, "changed": changed}
        (work / "comparison.json").write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
        if added or removed or changed:
            raise AssertionError(json.dumps(report, indent=2))
        print(f"PASS: {len(outputs)} sample files are byte-for-byte identical (SHA-256); see {work / 'comparison.json'}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--jar", type=Path, required=True)
    parser.add_argument("--snapshot", type=Path, required=True)
    parser.add_argument("--work-dir", type=Path, default=Path("build/sample-regression"))
    parser.add_argument("--capture", action="store_true")
    try:
        run(parser.parse_args())
    except (OSError, ValueError, AssertionError, subprocess.SubprocessError) as error:
        print(f"Sample regression failed: {error}", file=sys.stderr)
        sys.exit(1)
